SELECT fn_cp_import_case('biens-occupation-illicite-logement', '{"slug": "biens-occupation-illicite-logement", "title": "Le propriétaire a changé la serrure pendant leur absence", "theme_slug": "atteintes-biens", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 10 heures. Vous êtes appelée devant un appartement où des occupants se retrouvent bloqués à l''extérieur de leur logement, découvrant que le propriétaire a fait changer la serrure durant une absence de plusieurs jours, ce dernier justifiant son geste par des loyers impayés depuis plusieurs mois et une exaspération qu''il ne cache pas face à cette situation qui perdure. Cette initiative du propriétaire, aussi compréhensible que puisse paraître son exaspération, constitue elle-même une forme de justice privée qui contourne les voies légales normalement applicables à ce type de litige locatif.\n\nCette situation présente la particularité que le plaignant initial, ces occupants désormais empêchés d''accéder à leur logement, pourrait lui-même se trouver en tort sur le fond du litige locatif sous-jacent, cette configuration inversée nécessitant une approche qui ne prenne parti ni pour l''une ni pour l''autre des parties.\n\nCette configuration impose de traiter avec la même rigueur le changement de serrure illégal effectué par ce propriétaire et la situation des occupants, sans que la légitimité du grief locatif de l''un ne vienne excuser l''illégalité du geste de l''autre.", "questions": [{"position": 1, "max_points": 5, "label": "Comment traitez-vous le changement de serrure effectué par ce propriétaire sans pour autant minimiser son grief locatif légitime ?", "hint": "Le geste du propriétaire, aussi compréhensible soit sa frustration, reste une atteinte au domicile qui doit être traitée comme telle, indépendamment du bien-fondé de son grief locatif.", "perfect": "Je qualifie clairement ce changement de serrure comme un acte potentiellement constitutif d''une infraction, ce geste s''apparentant à une forme de justice privée qui contourne les voies légales prévues pour ce type de litige.\n\nJe reste attentive à ne pas minimiser la gravité de ce geste au prétexte que le grief locatif invoqué par ce propriétaire pourrait être légitime sur le fond, ces deux questions restant juridiquement distinctes.\n\nJe recueille néanmoins ses explications sur ce grief locatif, cette écoute ne valant pas validation de la méthode employée pour le faire valoir de manière unilatérale.\n\nJe l''informe clairement des voies légales qu''il aurait dû emprunter pour ce litige, notamment la procédure judiciaire d''expulsion, cette information pouvant éviter la réitération d''un tel geste à l''avenir.", "points": [{"position": 1, "label": "Qualifier clairement ce changement de serrure comme un acte potentiellement infractionnel", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : justice privée contournant les voies légales.", "groups": [{"position": 1, "keywords": ["acte qualifié", "justice privée", "voies légales contournées"]}]}, {"position": 2, "label": "Ne pas minimiser la gravité du geste malgré la légitimité possible du grief", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Questions juridiquement distinctes.", "groups": [{"position": 1, "keywords": ["gravité non minimisée", "questions distinctes", "grief légitime possible"]}]}, {"position": 3, "label": "Recueillir ses explications sans valider la méthode employée", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Écoute ne valant pas validation.", "groups": [{"position": 1, "keywords": ["explications recueillies", "méthode non validée", "écoute distincte"]}]}, {"position": 4, "label": "Informer des voies légales qu''il aurait dû emprunter", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Procédure judiciaire d''expulsion pour éviter la réitération.", "groups": [{"position": 1, "keywords": ["voies légales informées", "procédure d''expulsion", "réitération évitée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment traitez-vous la situation de ces occupants sans pour autant présumer de leur bon droit sur le fond du litige locatif ?", "hint": "Ces occupants, bloqués à l''extérieur de leur logement, doivent être pris en charge sans que cette prise en charge ne présume de l''issue du litige locatif sous-jacent.", "perfect": "Je reconnais leur droit immédiat à retrouver l''accès à leur logement, ce changement de serrure étant illégal indépendamment de la question des loyers impayés qui reste un litige distinct à trancher par les voies appropriées.\n\nJe reste attentive à ne pas prendre parti sur le fond de ce litige locatif, la question des loyers impayés relevant d''une procédure civile distincte de celle du rétablissement de leur accès au logement.\n\nJe recueille leurs explications sur la situation locative, cette écoute permettant de mieux cerner le contexte sans pour autant trancher moi-même ce différend qui ne relève pas de ma compétence.\n\nJe les informe des démarches à entreprendre pour faire valoir leurs droits, notamment auprès des instances compétentes en matière de litiges locatifs, cette orientation complétant utilement le traitement immédiat de leur situation.", "points": [{"position": 1, "label": "Reconnaître leur droit immédiat à retrouver l''accès à leur logement", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : changement de serrure illégal indépendamment des loyers.", "groups": [{"position": 1, "keywords": ["accès reconnu", "changement illégal", "litige distinct"]}]}, {"position": 2, "label": "Ne pas prendre parti sur le fond du litige locatif", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Procédure civile distincte du rétablissement de l''accès.", "groups": [{"position": 1, "keywords": ["pas de parti pris", "procédure civile", "litige distinct"]}]}, {"position": 3, "label": "Recueillir leurs explications sans trancher le différend", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Différend ne relevant pas de sa compétence.", "groups": [{"position": 1, "keywords": ["explications recueillies", "différend non tranché", "compétence limitée"]}]}, {"position": 4, "label": "Informer des démarches pour faire valoir leurs droits locatifs", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Instances compétentes en matière de litiges locatifs.", "groups": [{"position": 1, "keywords": ["démarches informées", "instances compétentes", "droits locatifs"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment organisez-vous concrètement le rétablissement de l''accès de ces occupants à leur logement ?", "hint": "Au-delà des questions de fond, une solution concrète et immédiate doit être trouvée pour permettre à ces occupants de retrouver l''accès à leur domicile.", "perfect": "Je recherche une solution concrète permettant à ces occupants de retrouver l''accès à leur logement, cette dimension pratique restant prioritaire indépendamment de l''issue du litige locatif sous-jacent.\n\nJe sollicite si nécessaire l''intervention de professionnels compétents pour permettre l''ouverture de cette serrure changée illégalement, cette démarche technique complétant le traitement de cette situation.\n\nJe reste attentive à la situation immédiate de ces occupants, notamment s''ils disposent d''une solution d''hébergement temporaire dans l''attente de la résolution de cette situation.\n\nJe consigne avec précision l''ensemble de cette intervention, cette documentation étant utile pour la suite du traitement tant du volet pénal que du litige locatif sous-jacent.", "points": [{"position": 1, "label": "Rechercher une solution concrète pour rétablir l''accès au logement", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : dimension pratique prioritaire.", "groups": [{"position": 1, "keywords": ["solution concrète", "accès rétabli", "priorité pratique"]}]}, {"position": 2, "label": "Solliciter des professionnels compétents pour l''ouverture de la serrure", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Démarche technique complétant la situation.", "groups": [{"position": 1, "keywords": ["professionnels sollicités", "serrure ouverte", "démarche technique"]}]}, {"position": 3, "label": "Rester attentive à leur situation immédiate d''hébergement", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Solution temporaire dans l''attente de résolution.", "groups": [{"position": 1, "keywords": ["hébergement temporaire", "situation immédiate", "attente de résolution"]}]}, {"position": 4, "label": "Consigner précisément l''intervention pour les deux volets", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Volet pénal et litige locatif sous-jacent.", "groups": [{"position": 1, "keywords": ["intervention consignée", "volet pénal", "litige locatif"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('biens-litige-proprietaire-locataire-acces', '{"slug": "biens-litige-proprietaire-locataire-acces", "title": "Il entre chez elle en son absence pour vérifier l''état du logement", "theme_slug": "atteintes-biens", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 17 heures. Une locataire vous contacte, furieuse, après avoir découvert par les caméras de son voisinage que son propriétaire est entré dans son appartement en son absence, muni de son propre jeu de clés, expliquant simplement vouloir vérifier l''état du logement sans l''avoir prévenue au préalable de cette visite. Cette intrusion, bien que le propriétaire estime agir dans le cadre de son droit de regard sur son bien, pose une question centrale sur la frontière entre ce qui relève d''un litige civil classique entre bailleur et locataire et ce qui pourrait constituer une infraction pénale distincte.\n\nCette situation, où un propriétaire pénètre dans un logement loué sans l''accord ni même l''information préalable de sa locataire, nécessite une analyse précise de cette frontière, le seul statut de propriétaire ne conférant pas un droit d''accès inconditionné au logement loué durant la durée du bail.\n\nCette configuration impose de traiter avec rigueur cette atteinte potentielle tout en tenant compte de la spécificité de la relation contractuelle qui lie ces deux parties, cette spécificité ne devant pas pour autant faire disparaître la protection due à cette locataire dans son domicile.", "questions": [{"position": 1, "max_points": 5, "label": "Comment qualifiez-vous cette intrusion du propriétaire en distinguant ce qui relève du civil de ce qui pourrait relever du pénal ?", "hint": "Le statut de propriétaire ne confère pas un droit d''accès inconditionné, cette distinction devant être clairement établie pour qualifier justement cette situation.", "perfect": "J''explique clairement à cette locataire que le statut de propriétaire ne confère pas un droit d''accès inconditionné à ce logement durant la période où elle en a la jouissance exclusive en tant que locataire.\n\nJe recueille avec précision les circonstances exactes de cette intrusion, notamment l''heure, la durée de cette visite et les éventuelles traces qu''elle aurait pu laisser dans le logement.\n\nJe reste attentive à distinguer ce qui relève d''un manquement contractuel civil, comme l''absence de préavis requis, de ce qui pourrait constituer une atteinte pénale plus sérieuse selon les circonstances précises de cette intrusion.\n\nJe consigne l''ensemble de ces éléments avec rigueur, cette documentation précise étant nécessaire pour permettre la qualification juridique appropriée de cette situation par les services compétents.", "points": [{"position": 1, "label": "Expliquer que le statut de propriétaire ne confère pas un droit d''accès inconditionné", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : jouissance exclusive du locataire durant le bail.", "groups": [{"position": 1, "keywords": ["droit d''accès non inconditionné", "jouissance exclusive", "statut clarifié"]}]}, {"position": 2, "label": "Recueillir précisément les circonstances de cette intrusion", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Heure, durée et traces éventuelles laissées.", "groups": [{"position": 1, "keywords": ["circonstances recueillies", "heure et durée", "traces laissées"]}]}, {"position": 3, "label": "Distinguer le manquement contractuel civil de l''atteinte pénale possible", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Absence de préavis versus atteinte plus sérieuse.", "groups": [{"position": 1, "keywords": ["distinction civil pénal", "manquement contractuel", "atteinte pénale possible"]}]}, {"position": 4, "label": "Consigner avec rigueur pour permettre la qualification appropriée", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Documentation précise pour les services compétents.", "groups": [{"position": 1, "keywords": ["consignation rigoureuse", "qualification appropriée", "services compétents"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment recueillez-vous les éléments de preuve de cette intrusion, notamment les images de vidéosurveillance mentionnées ?", "hint": "Les images de vidéosurveillance du voisinage constituent un élément de preuve précieux qui doit être recueilli avec méthode.", "perfect": "Je recueille avec précision les informations relatives à ces images de vidéosurveillance qu''elle mentionne, notamment leur origine exacte et les modalités selon lesquelles elle a pu y avoir accès.\n\nJe m''assure que ces images soient conservées et si possible transmises dans un cadre approprié, cette preuve visuelle constituant un élément particulièrement précieux pour établir la matérialité de cette intrusion.\n\nJe recueille également son témoignage détaillé sur l''état dans lequel elle a retrouvé son logement à son retour, ces éléments complétant utilement la preuve visuelle de cette intrusion.\n\nJe reste attentive à la chronologie précise des faits, cette rigueur temporelle étant nécessaire pour établir clairement le déroulement de cette intrusion contestée.", "points": [{"position": 1, "label": "Recueillir précisément les informations sur ces images de vidéosurveillance", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : origine et modalités d''accès à ces images.", "groups": [{"position": 1, "keywords": ["images recueillies", "origine précisée", "modalités d''accès"]}]}, {"position": 2, "label": "S''assurer que ces images soient conservées et transmises de manière appropriée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Preuve visuelle précieuse pour établir la matérialité.", "groups": [{"position": 1, "keywords": ["images conservées", "preuve visuelle", "matérialité établie"]}]}, {"position": 3, "label": "Recueillir son témoignage détaillé sur l''état retrouvé du logement", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Compléter la preuve visuelle de cette intrusion.", "groups": [{"position": 1, "keywords": ["témoignage détaillé", "état du logement", "preuve complétée"]}]}, {"position": 4, "label": "Établir la chronologie précise des faits", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Rigueur temporelle nécessaire pour le déroulement des faits.", "groups": [{"position": 1, "keywords": ["chronologie établie", "rigueur temporelle", "déroulement précis"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment orientez-vous cette locataire sur les suites possibles de cette situation, tant sur le plan pénal que sur le plan civil ?", "hint": "Cette locataire doit être informée des différentes voies qui s''offrent à elle, ces démarches pouvant se compléter mutuellement selon les circonstances établies.", "perfect": "Je l''informe des suites possibles de sa démarche sur le plan pénal, cette voie restant ouverte selon la qualification qui sera retenue au regard des circonstances précises de cette intrusion.\n\nJe l''oriente également vers les démarches civiles qu''elle pourrait entreprendre parallèlement, notamment auprès des instances compétentes en matière de litiges locatifs, ces deux voies pouvant se compléter selon sa situation.\n\nJe reste attentive à sa sécurité et à sa tranquillité pour l''avenir, cette intrusion pouvant légitimement l''inquiéter sur d''éventuelles récidives de la part de ce propriétaire.\n\nJe l''informe de son droit à faire changer la serrure à ses frais si cela s''avère nécessaire pour restaurer sa tranquillité, cette information pratique complétant utilement le traitement de cette situation.", "points": [{"position": 1, "label": "Informer des suites possibles sur le plan pénal", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : voie ouverte selon la qualification retenue.", "groups": [{"position": 1, "keywords": ["suites pénales informées", "qualification retenue", "voie ouverte"]}]}, {"position": 2, "label": "Orienter vers les démarches civiles complémentaires", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Instances compétentes en matière de litiges locatifs.", "groups": [{"position": 1, "keywords": ["démarches civiles", "litiges locatifs", "voies complémentaires"]}]}, {"position": 3, "label": "Rester attentive à sa sécurité et tranquillité pour l''avenir", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Inquiétude légitime sur d''éventuelles récidives.", "groups": [{"position": 1, "keywords": ["sécurité future", "tranquillité", "récidive possible"]}]}, {"position": 4, "label": "Informer de son droit à faire changer la serrure à ses frais", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Information pratique restaurant sa tranquillité.", "groups": [{"position": 1, "keywords": ["serrure changée", "information pratique", "tranquillité restaurée"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('biens-vol-entre-collegues-entreprise', '{"slug": "biens-vol-entre-collegues-entreprise", "title": "L''employeur a désigné un coupable avant votre arrivée", "theme_slug": "atteintes-biens", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 15 heures. Vous êtes appelée dans une entreprise pour un vol de matériel constaté dans les vestiaires du personnel, découvrant à votre arrivée que l''employeur a déjà désigné publiquement un salarié comme coupable présumé de ces faits, cette accusation ayant été formulée devant l''ensemble de l''équipe avant même que vous n''ayez pu commencer vos propres constatations. Cette présomption interne, déjà largement diffusée au sein de l''entreprise, place ce salarié désigné dans une situation de pression considérable qui pourrait affecter tant son ambiance de travail que son état psychologique.\n\nCette accusation préétablie par l''employeur, qui semble fonder sa conviction sur des éléments qu''il considère comme évidents mais qui n''ont fait l''objet d''aucune vérification objective par vos soins, nécessite une vigilance particulière pour ne pas endosser cette présomption avant d''avoir mené vos propres constatations avec la rigueur nécessaire.\n\nCette situation impose de traiter ce vol avec la même méthode que toute autre affaire, en écartant résolument toute influence de cette accusation déjà formée qui pourrait biaiser votre appréciation objective des faits et des responsabilités.", "questions": [{"position": 1, "max_points": 5, "label": "Comment évitez-vous d''endosser cette accusation préétablie par l''employeur avant d''avoir mené vos propres constatations ?", "hint": "L''accusation déjà formulée par l''employeur ne doit en aucun cas orienter prématurément votre appréciation objective de cette affaire.", "perfect": "Je reste factuelle et neutre face à cette accusation déjà formulée, cette présomption de l''employeur ne devant en aucun cas orienter prématurément mes propres constatations sur cette affaire.\n\nJe mène mes vérifications comme pour toute autre affaire de vol, sans accorder de crédit particulier à cette désignation qui n''a fait l''objet d''aucune vérification objective de ma part.\n\nJe recueille les explications de l''employeur sur les raisons de sa conviction, tout en restant attentive au fait que ces éléments ne constituent, à ce stade, que des soupçons subjectifs plutôt que des preuves établies.\n\nJe m''assure de recueillir également la version du salarié désigné, cette écoute équilibrée étant essentielle pour ne pas préjuger de sa culpabilité du seul fait de cette accusation déjà largement diffusée.", "points": [{"position": 1, "label": "Rester factuelle et neutre face à cette accusation déjà formulée", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : présomption ne devant pas orienter les constatations.", "groups": [{"position": 1, "keywords": ["neutralité maintenue", "accusation non endossée", "constatations objectives"]}]}, {"position": 2, "label": "Mener les vérifications comme pour toute autre affaire de vol", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Sans crédit particulier à la désignation non vérifiée.", "groups": [{"position": 1, "keywords": ["vérifications standard", "pas de crédit particulier", "désignation non vérifiée"]}]}, {"position": 3, "label": "Recueillir les explications de l''employeur en restant attentive à leur nature subjective", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Soupçons subjectifs plutôt que preuves établies.", "groups": [{"position": 1, "keywords": ["explications recueillies", "soupçons subjectifs", "preuves non établies"]}]}, {"position": 4, "label": "Recueillir également la version du salarié désigné", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Écoute équilibrée sans préjuger de la culpabilité.", "groups": [{"position": 1, "keywords": ["version recueillie", "écoute équilibrée", "pas de préjugé"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment protégez-vous ce salarié désigné de la pression que cette accusation publique fait peser sur lui ?", "hint": "Ce salarié, désigné publiquement avant toute vérification, subit une pression considérable qui mérite d''être prise en compte au-delà du seul traitement de l''infraction.", "perfect": "Je reste attentive à l''état de ce salarié désigné, cette accusation publique et prématurée pouvant avoir des conséquences importantes sur son ambiance de travail et son état psychologique.\n\nJe l''informe clairement qu''aucune conclusion n''est à ce stade établie sur sa responsabilité, cette clarification pouvant atténuer quelque peu la pression qu''il subit du fait de cette désignation publique.\n\nJe recueille sa version des faits avec la même rigueur que pour n''importe quel témoin ou suspect, cette égalité de traitement étant essentielle pour ne pas ajouter à la pression qu''il subit déjà.\n\nJe reste attentive aux conséquences que cette situation pourrait avoir sur ses relations professionnelles futures, cette dimension méritant d''être signalée si des mesures de protection s''avéraient nécessaires.", "points": [{"position": 1, "label": "Rester attentive à l''état de ce salarié face à l''accusation publique", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : conséquences sur l''ambiance de travail et l''état psychologique.", "groups": [{"position": 1, "keywords": ["état du salarié", "accusation publique", "conséquences psychologiques"]}]}, {"position": 2, "label": "L''informer clairement qu''aucune conclusion n''est établie sur sa responsabilité", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Clarification atténuant la pression subie.", "groups": [{"position": 1, "keywords": ["aucune conclusion établie", "clarification apportée", "pression atténuée"]}]}, {"position": 3, "label": "Recueillir sa version avec la même rigueur que pour tout suspect", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Égalité de traitement sans ajouter à la pression.", "groups": [{"position": 1, "keywords": ["version recueillie", "égalité de traitement", "pression non ajoutée"]}]}, {"position": 4, "label": "Rester attentive aux conséquences sur ses relations professionnelles futures", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Mesures de protection signalées si nécessaires.", "groups": [{"position": 1, "keywords": ["relations professionnelles", "conséquences futures", "protection signalée"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment recueillez-vous les éléments objectifs nécessaires pour établir les responsabilités réelles dans ce vol ?", "hint": "Au-delà de l''accusation préétablie, des éléments objectifs doivent être recherchés méthodiquement pour établir les responsabilités réelles.", "perfect": "Je recherche les éléments objectifs disponibles, comme un éventuel système de contrôle d''accès aux vestiaires ou des équipements de vidéosurveillance qui pourraient éclairer objectivement les circonstances de ce vol.\n\nJe recueille les témoignages de l''ensemble des collègues ayant accès à ces vestiaires, cette approche large évitant de se limiter à la seule personne désignée par l''employeur.\n\nJe m''intéresse aux éventuels antécédents de tensions au sein de cette équipe qui pourraient expliquer pourquoi l''employeur ou d''autres collègues ont pu orienter leurs soupçons vers cette personne spécifique.\n\nJe consigne l''ensemble de ces éléments avec la rigueur nécessaire pour permettre un traitement objectif de cette affaire, indépendamment de l''accusation prématurée qui avait été formulée avant mon arrivée.", "points": [{"position": 1, "label": "Rechercher les éléments objectifs disponibles comme la vidéosurveillance", "weight": 